var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fix #3: CacheService cannot capture scoped IUserService in a singleton.
// Use a scoped lifetime so each request gets its own instance with a valid scope.
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
// Fix #2: ConfigureHttpMessageHandlerBuilder was removed in .NET 9.
// Use ConfigurePrimaryHttpMessageHandler instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() =>
        new HttpClientHandler { UseCookies = false });
// Fix #4: .NET 9 redacts HTTP client headers at Trace level by default.
// Allow headers needed for debugging to appear in logs.
builder.Services.AddHttpClient("api")
    .RedactLoggedHeaders(Enumerable.Empty<string>());
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

